# ex-dimension: the cheap "is this relaxation blind?" test, for representations whose free algebra is too big to store.
# R_0 = the B-module generated by the inputs (E_l = iota_U in slot l); step j: c_j = a random element of R_{j-1}
# (a generic content: any element of the module is an A-combination of the sources), u_j = rho(W_{r_j}) c_j,
# R_j = R_{j-1} + B-module generated by u_j.  Ambient = (C_G iota_U)^W, C_G = algebra of all letters.
# full (dim R_n = W * dim C_G iota_U)  =>  every target is an A-combination of the sources: the shape is exactly
# solvable in this relaxation (and its program map is dominant), so the representation carries no information on it.
# Not full proves nothing by itself (a random program may be unlucky only on a measure-zero set; generic = maximal).
import sys, os, json, time, numpy as np, warnings
warnings.filterwarnings('ignore')
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from dimcount import letters, rep_fn

class Module:
    def __init__(self, gens, shape, tol=1e-9):
        self.gens = gens; self.shape = shape; self.tol = tol      # shape = (d, cols): vectors are d x cols matrices
        self.B = np.zeros((0, shape[0] * shape[1]), complex)
    def _orth(self, X):
        for _ in range(2):
            if self.B.shape[0]: X = X - (X @ self.B.conj().T) @ self.B
        return X
    def add(self, X0):          # add the module generated by the rows of X0 (each a flattened d x cols matrix)
        d, cols = self.shape
        frontier = self._accept(X0)
        while frontier.shape[0]:
            new = []
            for g in self.gens:
                cand = np.einsum('ij,ajk->aik', g, frontier.reshape(-1, d, cols)).reshape(-1, d * cols)
                acc = self._accept(cand)
                if acc.shape[0]: new.append(acc)
            frontier = np.concatenate(new, 0) if new else np.zeros((0, d * cols), complex)
        return self.B.shape[0]
    def _accept(self, X):
        X = self._orth(X)
        if not X.shape[0]: return X
        nrm = np.linalg.norm(X, axis=1); X = X[nrm > self.tol]
        if not X.shape[0]: return X
        u, sv, vh = np.linalg.svd(X, full_matrices=False)
        keep = sv > self.tol * max(1.0, sv[0]) if sv.size else []
        nb = vh[keep]
        if not nb.shape[0]: return nb
        nb = self._orth(nb); q, _ = np.linalg.qr(nb.T); nb = q.T
        self.B = np.concatenate([self.B, nb], 0)
        return nb

def run(m, rep, W, steps, label='', seed=0, U='diag'):
    t0 = time.time(); rng = np.random.default_rng(seed)
    free, Wr = letters(m, 'engine'); f = rep_fn(rep)
    F = [f(g) for g in free]; Wr = [f(g) for g in Wr]; d = F[0].shape[0]; n0 = 1 << m
    assert U == 'diag' and rep == 'VV'
    Um = np.zeros((d, n0), complex)
    for x in range(n0): Um[x * n0 + x, x] = 1
    for g in F: assert np.allclose(Um @ (Um.T @ (g @ Um)), g @ Um)
    u = n0
    amb = Module(F + [Wr[1]], (d, u)); gU = amb.add(Um.reshape(1, -1))
    R = Module(F, (d, u * W))
    E = np.zeros((W, d, u * W), complex)
    for l in range(W): E[l, :, l * u:(l + 1) * u] = Um
    dims = [R.add(E.reshape(W, -1))]
    for r in steps:
        coeff = rng.normal(size=R.B.shape[0]) + 1j * rng.normal(size=R.B.shape[0])
        c = (coeff @ R.B).reshape(d, u * W)
        uj = Wr[r] @ c
        dims.append(R.add((uj / np.linalg.norm(uj)).reshape(1, -1)))
    out = dict(label=label, m=m, rep=rep, U=U, W=W, steps=steps, d=d, u=u, gU=gU, ambient=W * gU, dims=dims,
               full=dims[-1] == W * gU, sec=round(time.time() - t0, 1))
    return out

if __name__ == '__main__':
    for sp in json.loads(sys.argv[1]):
        print(json.dumps(run(**sp)), flush=True)
